<script setup lang="ts">
import { computed, onMounted, ref } from 'vue';
type ToolName = 'list_directory' | 'read_file' | 'write_file' | 'get_system_info';
const agents=ref<string[]>([]),selectedAgent=ref(''),loadingAgents=ref(false),totpLoading=ref(true),totp=ref<{configured?:boolean;account?:string;qrDataUrl?:string;error?:string}>();
const directory=ref('C:\\Users\\bombl\\Desktop'),readPath=ref('C:\\Users\\bombl\\Desktop\\mcp-test.txt'),writePath=ref('C:\\Users\\bombl\\Desktop\\mcp-created.txt'),content=ref('Hello from MCP Gateway!'),busyTool=ref<ToolName|''>(''),output=ref(''),outputError=ref(false),lastUpdated=ref('');
const connectedCount=computed(()=>agents.value.length);
async function requestJson<T>(url:string,init?:RequestInit):Promise<T>{const r=await fetch(url,init);const body=await r.json().catch(()=>({}));if(!r.ok)throw new Error(body.error||`${r.status} ${r.statusText}`);return body as T;}
async function loadTotp(){totpLoading.value=true;try{totp.value=await requestJson('/_admin/totp');}catch(e){totp.value={error:e instanceof Error?e.message:String(e)};}finally{totpLoading.value=false;}}
async function refreshAgents(){loadingAgents.value=true;try{const h=await requestJson<{agents:string[]}>('/healthz');agents.value=h.agents;if(!agents.value.includes(selectedAgent.value))selectedAgent.value=agents.value[0]??'';lastUpdated.value=new Date().toLocaleTimeString();}catch(e){outputError.value=true;output.value=`Unable to load gateway status: ${e instanceof Error?e.message:String(e)}`;}finally{loadingAgents.value=false;}}
async function runTool(tool:ToolName){if(!selectedAgent.value)return;busyTool.value=tool;outputError.value=false;output.value='';const args:Record<string,string>={agentId:selectedAgent.value};if(tool==='list_directory')args.path=directory.value;if(tool==='read_file')args.path=readPath.value;if(tool==='write_file'){args.path=writePath.value;args.content=content.value;}try{const r=await requestJson<{result:unknown}>('/_admin/call',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({tool,args})});output.value=JSON.stringify(r.result,null,2);}catch(e){outputError.value=true;output.value=e instanceof Error?e.message:String(e);}finally{busyTool.value='';}}
onMounted(()=>{void loadTotp();void refreshAgents();});
</script>
<template><div class="shell">
<header class="topbar"><a class="brand" href="/"><span class="brand-mark">M</span><span>mcp<span class="brand-muted">/gateway</span></span></a><div class="topbar-right"><span class="live-dot"></span>LOCAL ADMIN CONSOLE<span class="version">HTTP</span></div></header>
<main><section class="hero"><div><div class="eyebrow">CONTROL PLANE <span>/</span> OVERVIEW</div><h1>Gateway console</h1><p>Monitor connected agents and run administrative actions from one place.</p></div><button class="button button-quiet" :disabled="loadingAgents" @click="refreshAgents"><span :class="{spinning:loadingAgents}">↻</span> Refresh status</button></section>
<section class="stats-grid"><article class="stat-card"><div class="stat-label">CONNECTED AGENTS</div><div class="stat-value">{{connectedCount.toString().padStart(2,'0')}}</div><div class="stat-foot"><span class="live-dot"></span>{{connectedCount?'Agent connection active':'Waiting for connections'}}</div></article><article class="stat-card"><div class="stat-label">GATEWAY STATUS</div><div class="stat-value status-value"><span class="status-indicator"></span>Online</div><div class="stat-foot">HTTP service responding</div></article><article class="stat-card"><div class="stat-label">LAST STATUS CHECK</div><div class="stat-value time-value">{{lastUpdated||'—'}}</div><div class="stat-foot">Local server time</div></article></section>
<div class="content-grid"><div class="main-column"><section class="panel"><div class="panel-heading"><div><div class="eyebrow">CONNECTIONS</div><h2>Connected agents</h2></div><span class="count-pill">{{connectedCount}} connected</span></div><div v-if="loadingAgents&&!agents.length" class="empty-state">Checking agent connections…</div><div v-else-if="!agents.length" class="empty-state"><span class="empty-icon">⌁</span><strong>No agents connected</strong><span>Start an agent to see it appear here.</span></div><div v-else class="agent-list"><div v-for="agent in agents" :key="agent" class="agent-row"><span class="agent-avatar">⌘</span><div class="agent-details"><strong>{{agent}}</strong><span>Connected and ready</span></div><span class="agent-status"><i></i> Online</span></div></div></section>
<section class="panel actions-panel"><div class="panel-heading"><div><div class="eyebrow">REMOTE OPERATIONS</div><h2>Agent tools</h2></div><span class="subtle-tag">4 available actions</span></div><label class="field-label" for="agent-select">TARGET AGENT</label><select id="agent-select" v-model="selectedAgent" class="field" :disabled="!agents.length"><option value="" disabled>Select an agent</option><option v-for="agent in agents" :key="agent" :value="agent">{{agent}}</option></select>
<div class="tool-block"><div class="tool-title"><span class="tool-icon">▤</span><div><strong>Browse directory</strong><small>List files and folders at a path</small></div></div><div class="inline-form"><input v-model="directory" class="field" aria-label="Directory path" placeholder="/path/to/directory" @keyup.enter="runTool('list_directory')"/><button class="button button-primary" :disabled="!selectedAgent||!!busyTool" @click="runTool('list_directory')">{{busyTool==='list_directory'?'Running…':'List directory'}}</button></div></div>
<div class="tool-block"><div class="tool-title"><span class="tool-icon">⌕</span><div><strong>Read file</strong><small>Read a UTF-8 file from the agent</small></div></div><div class="inline-form"><input v-model="readPath" class="field" aria-label="File path to read" placeholder="/path/to/file" @keyup.enter="runTool('read_file')"/><button class="button button-secondary" :disabled="!selectedAgent||!!busyTool" @click="runTool('read_file')">{{busyTool==='read_file'?'Reading…':'Read file'}}</button></div></div>
<div class="tool-block"><div class="tool-title"><span class="tool-icon">↥</span><div><strong>Write file</strong><small>Write text content to a file on the agent</small></div></div><input v-model="writePath" class="field spaced-field" aria-label="File path to write" placeholder="/path/to/file"/><textarea v-model="content" class="field content-field" aria-label="File content" rows="3"></textarea><div class="form-actions"><button class="button button-secondary" :disabled="!selectedAgent||!!busyTool" @click="runTool('write_file')">{{busyTool==='write_file'?'Writing…':'Write file'}}</button></div></div>
<div class="tool-block tool-last"><div class="tool-title"><span class="tool-icon">⌘</span><div><strong>System information</strong><small>Inspect the selected agent environment</small></div><button class="button button-secondary push-right" :disabled="!selectedAgent||!!busyTool" @click="runTool('get_system_info')">{{busyTool==='get_system_info'?'Loading…':'Get info'}}</button></div></div></section>
</div>
<aside class="side-column"><section v-if="output" class="panel result-panel"><div class="panel-heading"><div><div class="eyebrow">EXECUTION</div><h2>Latest result</h2></div><button class="text-button" @click="output=''">Clear</button></div><pre :class="{'result-error':outputError}">{{output}}</pre></section><section class="panel security-panel"><div class="panel-heading"><div><div class="eyebrow">ACCOUNT SECURITY</div><h2>Authenticator</h2></div><span class="shield">◆</span></div><p class="panel-description">Scan this QR code with Google Authenticator, Microsoft Authenticator, 1Password, or another TOTP app. This setup is only available from the local admin page.</p><div class="qr-wrap"><div v-if="totpLoading" class="qr-placeholder">Loading secure setup…</div><img v-else-if="totp?.qrDataUrl" :src="totp.qrDataUrl" alt="Authenticator setup QR code"/><div v-else class="qr-placeholder error-text">{{totp?.error||'Unable to load authenticator setup.'}}</div></div><div v-if="totp?.configured" class="configured-note"><span class="live-dot"></span><div><strong>Authenticator configured</strong><small>Account · {{totp.account}}</small></div></div></section><section class="info-card"><div class="info-icon">i</div><div><strong>Local access only</strong><p>The admin console is intentionally restricted to direct local connections. Requests through a reverse proxy are not exposed.</p></div></section></aside></div><footer>CHATGPT MCP GATEWAY <span>·</span> LOCAL ADMINISTRATION</footer></main></div></template>
